    private function safeExternalUrl(string $url):bool{$parts=parse_url($url);if(!$parts||!in_array(strtolower($parts['scheme']??''),['http','https'],true)||empty($parts['host']))return false;$host=strtolower($parts['host']);if($host==='localhost'||str_ends_with($host,'.localhost')||str_ends_with($host,'.local'))return false;if(filter_var($host,FILTER_VALIDATE_IP)&&!filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return false;return true;}
