    private function audit(Request $r,string $a,string $type,string $id,mixed $after):void{DB::table('audit_events')->insert(['id'=>(string)Str::uuid(),'tenant_id'=>$this->t($r),'actor_id'=>$this->u($r)->id,'actor_source'=>'user','action'=>$a,'entity_type'=>$type,'entity_id'=>$id,'after_json'=>json_encode($after),'request_id'=>$r->attributes->get('request_id'),'created_at'=>now()]);}
    private function project(object $p):array{$x=(array)$p;$x['tags']=$this->arr($x['tags']??null);$x['metadata']=is_string($x['metadata']??null)?json_decode($x['metadata'],true):($x['metadata']??[]);$x['member_ids']=DB::table('project_people')->where('project_id',$p->id)->where('project_role','member')->pluck('user_id')->all();$x['reviewer_ids']=DB::table('project_people')->where('project_id',$p->id)->where('project_role','reviewer')->pluck('user_id')->all();return $x;}
    public function projectScopeOptions(Request $r){$d=$r->validate(['type'=>'required|in:division,team,user','q'=>'nullable|string|max:80','limit'=>'nullable|integer|min:1|max:50']);$term=trim($d['q']??'');$limit=(int)($d['limit']??20);$like='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$term).'%';if($d['type']==='division'){$q=DB::table('divisions')->select('id','name as label')->where('tenant_id',$this->t($r));if($term!=='')$q->where('name','ilike',$like);$items=$q->orderBy('name')->limit($limit)->get();}elseif($d['type']==='team'){$q=DB::table('teams as t')->join('divisions as d',function($join){$join->on('d.id','=','t.division_id')->on('d.tenant_id','=','t.tenant_id');})->select('t.id',DB::raw("t.name || ' · ' || d.name as label"))->where('t.tenant_id',$this->t($r));if($term!=='')$q->where(function($x)use($like){$x->where('t.name','ilike',$like)->orWhere('d.name','ilike',$like);});$items=$q->orderBy('t.name')->limit($limit)->get();}else{$q=DB::table('users')->select('id',DB::raw("name || ' · ' || email as label"))->where('tenant_id',$this->t($r));if($term!=='')$q->where(function($x)use($like){$x->where('name','ilike',$like)->orWhere('email','ilike',$like);});$items=$q->orderBy('name')->limit($limit)->get();}return $this->ok($r,$this->rows($items));}    public function projects(Request $r){$q=DB::table('projects')->where('tenant_id',$this->t($r))->whereNull('deleted_at');if($r->team_id)$q->where('team_id',$r->team_id);return $this->ok($r,$q->orderByRaw('simulation_batch_id IS NULL DESC')->orderByDesc('created_at')->get()->map(fn($p)=>$this->project($p))->all());}
    public function projectById(Request $r,string $id){$p=DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$id)->whereNull('deleted_at')->first();return $p?$this->ok($r,$this->project($p)):$this->fail($r,'NOT_FOUND','project not found',404);}
    public function createProject(Request $r){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400);$d=$r->validate(['name'=>'required|string|max:160','team_id'=>'required|uuid','project_type'=>'nullable|string|max:40','tags'=>'array|max:50','tags.*'=>'string|max:60','preliminary_note_template_id'=>'nullable|uuid','preliminary_notes'=>'nullable|string|max:200000','source'=>'nullable|string|max:100','source_ref'=>'nullable|string|max:200','metadata'=>'array','metadata.project_scope'=>'nullable|array','metadata.project_scope.division_ids'=>'array|max:50','metadata.project_scope.division_ids.*'=>'uuid','metadata.project_scope.team_ids'=>'array|max:100','metadata.project_scope.team_ids.*'=>'uuid','metadata.project_scope.user_ids'=>'array|max:100','metadata.project_scope.user_ids.*'=>'uuid','member_ids'=>'array|max:100','member_ids.*'=>'uuid','reviewer_ids'=>'array|max:50','reviewer_ids.*'=>'uuid']);$tenant=$this->t($r);if(!DB::table('teams')->where('tenant_id',$tenant)->where('id',$d['team_id'])->exists())return $this->fail($r,'VALIDATION_ERROR','team does not belong to this workspace',422,'team_id');$people=array_values(array_unique(array_merge($d['member_ids']??[],$d['reviewer_ids']??[])));if(DB::table('users')->where('tenant_id',$tenant)->whereIn('id',$people)->count()!==count($people))return $this->fail($r,'VALIDATION_ERROR','one or more users do not belong to this workspace',422,'member_ids');$scope=$d['metadata']['project_scope']??[];foreach([['division_ids','divisions'],['team_ids','teams'],['user_ids','users']] as [$key,$table]){$ids=array_values(array_unique($scope[$key]??[]));if(DB::table($table)->where('tenant_id',$tenant)->whereIn('id',$ids)->count()!==count($ids))return $this->fail($r,'VALIDATION_ERROR','one or more project scope values do not belong to this workspace',422,'metadata.project_scope.'.$key);}$id=(string)Str::uuid();return DB::transaction(function()use($r,$d,$id){DB::statement('SELECT pg_a