    public function linkGithubRepository(Request $r,string $id){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400,'Idempotency-Key');$d=$r->validate(['repository'=>'required|string|max:240']);$project=DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$id)->whereNull('deleted_at')->first();if(!$project)return $this->fail($r,'NOT_FOUND','project not found',404);$settings=DB::table('github_integration_settings')->where('tenant_id',$this->t($r))->where('is_enabled',true)->first();if(!$settings)return $this->fail($r,'VALIDATION_ERROR','GitHub integration must be enabled in Settings first',400,'repository');$repository=trim(preg_replace('#^https?://github\.com/#i','',trim($d['repository'])),'/');$repository=preg_replace('/\.git$/i','',$repository);if(!preg_match('/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/',$repository))return $this->fail($r,'VALIDATION_ERROR','repository must use owner/repository format',400,'repository');$existing=DB::table('github_project_links')->where('tenant_id',$this->t($r))->where('project_id',$id)->first();if($existing)return $this->ok($r,['id'=>$existing->id,'project_id'=>$id,'repository'=>$existing->repository,'webhook_url'=>'/api/v1/integrations/github/webhook','secret_configured'=>true]);$linkID=(string)Str::uuid();$secret=Str::random(48);DB::table('github_project_links')->insert(['id'=>$linkID,'tenant_id'=>$this->t($r),'project_id'=>$id,'repository'=>$repository,'webhook_secret'=>Crypt::encryptString($secret),'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'create','github_project_link',$linkID,['project_id'=>$id,'repository'=>$repository]);return $this->ok($r,['id'=>$linkID,'project_id'=>$id,'repository'=>$repository,'webhook_url'=>'/api/v1/integrations/github/webhook','webhook_secret'=>$secret],201);}
    public function githubWebhook(Request $r){$raw=$r->getContent();if(strlen($raw)>1048576)return response()->json(['error'=>'payload too large'],413);$payload=json_decode($raw,true);$repository=$payload['repository']['full_name']??null;$delivery=trim((string)$r->header('X-GitHub-Delivery'));$event=trim((string)$r->header('X-GitHub-Event'));$signature=trim((string)$r->header('X-Hub-Signature-256'));if(!$repository||!$delivery||!$event||!$signature)return response()->json(['error'=>'invalid webhook headers'],400);$links=DB::table('github_project_links')->where('repository',$repository)->limit(20)->get();$link=null;foreach($links as $candidate){try{$secret=Crypt::decryptString($candidate->webhook_secret);}catch(\Throwable){continue;}$expected='sha256='.hash_hmac('sha256',$raw,$secret);if(hash_equals($expected,$signature)){$link=$candidate;break;}}if(!$link)return response()->json(['error'=>'signature verification failed'],403);if(DB::table('github_webhook_events')->where('link_id',$link->id)->where('delivery_id',$delivery)->exists())return response()->json(['accepted'=>true,'duplicate'=>true]);return DB::transaction(function()use($r,$payload,$delivery,$event,$link){$eventID=(string)Str::uuid();DB::table('github_webhook_events')->insert(['id'=>$eventID,'tenant_id'=>$link->tenant_id,'link_id'=>$link->id,'delivery_id'=>$delivery,'event_type'=>$event,'payload_json'=>json_encode($payload),'processed_at'=>now()]);$created=0;if($event==='push'){foreach(array_slice($payload['commits']??[],0,20) as $commit){$taskID=(string)Str::uuid();$message=trim((string)($commit['message']??'GitHub commit'));$sha=substr((string)($commit['id']??''),0,12);DB::table('tasks')->insert(['id'=>$taskID,'tenant_id'=>$link->tenant_id,'project_id'=>$link->project_id,'assignee_id'=>null,'title'=>'Commit: '.mb_substr(strtok($message,"\n"),0,120),'description'=>'GitHub commit '.$sha."\n\n".$message."\n\n".($commit['url']??''),'board_column'=>'done','position'=>(int)DB::table('tasks')->where('tenant_id',$link->tenant_id)->where('project_id',$link->project_id)->max('position')+1,'due_date'=>$commit['timestamp']??now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('audit_events')->insert(['id'=>(string)Str::uuid(),'tenant_id'=>$link->tenant_id,'actor_id'=>null,'actor_source'=>'github','action'=>'create','entity_type'=>'task','entity_id'=>$taskID,'before_json'=>null,'after_json'=>json_encode(['title'=>'Commit: '.$message,'board_column'=>'done']),'request_id'=>null,'created_at'=>now()]);$created++;}}return response()->json(['accepted'=>true,'activities_created'=>$created],202);});}
    public function updateProject(Request $r,string $id){$tenant=$this->t($r);$project=DB::table('projects')->where('tenant_id',$tenant)->where('id',$id)->whereNull('deleted_at')->first();if(!$project)return $this->fail($r,'NOT_FOUND','project not found',404);$d=$r->validate(['name'=>'sometimes|required|string|max:160','team_id'=>'sometimes|required|uuid','status'=>'sometimes|string|max:40','metadata'=>'sometimes|array','project_type'=>'sometimes|nullable|string|max:40','tags'=>'sometimes|array|max:50','tags.*'=>'string|max:60','preliminary_note_template_id'=>'sometimes|nullable|uuid','preliminary_notes'=>'sometimes|nullable|string|max:200000','source'=>'sometimes|nullable|string|max:100','source_ref'=>'sometimes|nullable|string|max:200','member_ids'=>'sometimes|array|max:100','member_ids.*'=>'uuid','reviewer_ids'=>'sometimes|array|max:50','reviewer_ids.*'=>'uuid','knowledge_page_ids'=>'sometimes|array|max:100','knowledge_page_ids.*'=>'uuid']);if(isset($d['team_id'])&&!DB::table('teams')->where('tenant_id',$tenant)->where('id',$d['team_id'])->exists())return $this->fail($r,'VALIDATION_ERROR','team does not belong to this workspace',422,'team_id');$people=array_values(array_unique(array_merge($d['member_ids']??[],$d['reviewer_ids']??[])));if($people&&DB::table('users')->where('tenant_id',$tenant)->whereIn('id',$people)->count()!==count($people))return $this->fail($r,'VALIDATION_ERROR','one or more users do not belong to this workspace',422,'member_ids');if(!empty($d['preliminary_note_template_id'])&&!DB::table('preliminary_note_templates')->where('tenant_id',$tenant)->where('id',$d['preliminary_note_template_id'])->exists())return $this->fail($r,'VALIDATION_ERROR','preliminary note does not belong to this workspace',422,'preliminary_note_template_id');return DB::transaction(function()use($r,$id,$tenant,$d){$members=$d['member_ids']??null;$reviewers=$d['reviewer_ids']??null;unset($d['member_ids'],$d['reviewer_ids'],$d['knowledge_page_ids']);if(isset($d['name']))$d['na