    public function noteTemplates(Request $r){$tenant=$this->t($r);$usage=[];foreach(DB::table('projects')->select('metadata')->where('tenant_id',$tenant)->whereNull('deleted_at')->get() as $project){$metadata=json_decode($project->metadata??'{}',true)??[];$knowledgeID=$metadata['preliminary_knowledge_id']??null;if($knowledgeID)$usage[$knowledgeID]=($usage[$knowledgeID]??0)+1;}$base=DB::table('preliminary_note_templates')->select('id','name','content_markdown','updated_at')->where('tenant_id',$tenant)->get()->map(fn($x)=>['id'=>$x->id,'name'=>$x->name,'content_markdown'=>$x->content_markdown,'source'=>'template','updated_at'=>$x->updated_at,'usage_count'=>(int)DB::table('projects')->where('tenant_id',$tenant)->where('preliminary_note_template_id',$x->id)->count()]);$knowledge=DB::table('wiki_pages as w')->join('knowledge_types as kt','kt.id','=','w.knowledge_type_id')->select('w.id','w.title','w.content','w.updated_at')->where('w.tenant_id',$tenant)->where('kt.slug','project_preliminary_notes')->where('w.knowledge_source_mode','internal')->whereNull('w.deleted_at')->get()->map(fn($x)=>['id'=>'knowledge:'.$x->id,'name'=>$x->title,'content_markdown'=>$x->content,'source'=>'knowledge','updated_at'=>$x->updated_at,'usage_count'=>$usage[$x->id]??0]);return $this->ok($r,$base->concat($knowledge)->sortByDesc('updated_at')->values());}    public function finishAttachments(Request $r,string $project){if(!DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$project)->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','project not found',404);return $this->ok($r,$this->rows(DB::table('project_finish_attachments')->select('id','project_id','filename','content_type','size_bytes','evidence_type','external_url','uploaded_by','created_at','updated_at')->where('tenant_id',$this->t($r))->where('project_id',$project)->orderByDesc('created_at')));}
    public function uploadFinishAttachment(Request $r,string $project){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400);if(!DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$project)->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','project not found',404);$r->validate(['file'=>'required|file|max:10240']);$file=$r->file('file');$path=$file->getRealPath();$head=file_get_contents($path,false,null,0,16);$mime=str_starts_with($head,'%PDF-')?'application/pdf':(str_starts_with($head,"\xFF\xD8\xFF")?'image/jpeg':(str_starts_with($head,"\x89PNG\x0D\x0A\x1A\x0A")?'image/png':(strlen($head)>=12&&substr($head,0,4)==='RIFF'&&substr($head,8,4)==='WEBP'?'image/webp':null)));if(!$mime)return $this->fail($r,'VALIDATION_ERROR','File content must be PDF, JPEG, PNG, or WebP',422,'file');$filename=mb_substr(basename(str_replace('\\','/',$file->getClientOriginalName())),0,255);$id=(string)Str::uuid();$item=DB::transaction(function()use($r,$project,$filename,$mime,$file,$path,$id){$now=now();DB::statement("INSERT INTO project_finish_attachments (id,tenant_id,project_id,filename,content_type,size_bytes,content,evidence_type,external_url,uploaded_by,created_at,updated_at) VALUES (?,?,?,?,?,?,decode(?, 'base64'),?,?,?,?,?)",[$id,$this->t($r),$project,$filename,$mime,$file->getSize(),base64_encode(file_get_contents($path)),'file',null,$this->u($r)->id,$now,$now]);$created=(array)DB::table('project_finish_attachments')->select('id','project_id','filename','content_type','size_bytes','evidence_type','external_url','uploaded_by','created_at','updated_at')->where('tenant_id',$this->t($r))->where('id',$id)->first();$this->audit($r,'create','project_finish_attachment',$id,array_diff_key($created,['external_url'=>true]));return $created;});return $this->ok($r,$item,201);}
    public function createFinishLink(Request $r,string $project){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400,'Idempotency-Key');if(!DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$project)->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','project not found',404);$d=$r->validate(['title'=>'required|string|max:255','url'=>'required|url|max:2048']);$url=trim($d['url']);if(!$this->safeExternalUrl($url))return $this->fail($r,'VALIDATION_ERROR','External proof must use a safe public HTTP(S) URL',422,'url');$existing=DB::table('project_finish_attachments')->where('tenant_id',$this->t($r))->where('project_id',$project)->where('evidence_type','url')->where('external_url',$url)->first();if($existing)return $this->ok($r,(array)$existing);$id=(string)Str::uuid();DB::table('project_finish_attachments')->insert(['id'=>$id,'tenant_id'=>$this->t($r),'project_id'=>$project,'filename'=>trim($d['title']),'content_type'=>null,'size_bytes'=>null,'content'=>null,'evidence_type'=>'url','external_url'=>$url,'uploaded_by'=>$this->u($r)->id,'created_at'=>now(),'updated_at'=>now()]);$item=(array)DB::table('project_finish_attachments')->select('id','project_id','filename','content_type','size_bytes','evidence_type','external_url','uploaded_by','created_at','updated_at')->where('tenant_id',$this->t($r))->where('id',$id)->first();$this->audit($r,'create','project_finish_evidence_link',$id,['project_id'=>$project,'filename'=>$item['filename'],'host'=>parse_url($url,PHP_URL_HOST)]);return $this->ok($r,$item,201);}
