    public function updateTask(Request $r,string $id){$task=DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$id)->whereNull('deleted_at')->first();if(!$task)return $this->fail($r,'NOT_FOUND','task not found',404);$d=$r->validate(['title'=>'sometimes|required|string|max:160','description'=>'sometimes|nullable|string|max:200000','board_column'=>'sometimes|in:todo,in_progress,review,done','position'=>'sometimes|integer|min:0','due_date'=>'sometimes|nullable|date','assignee_id'=>'sometimes|nullable|uuid']);if(array_key_exists('assignee_id',$d)&&$d['assignee_id']&&!DB::table('users')->where('tenant_id',$this->t($r))->where('id',$d['assignee_id'])->exists())return $this->fail($r,'VALIDATION_ERROR','assignee does not belong to this workspace',422,'assignee_id');$d['updated_at']=now();DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$id)->update($d);$item=(array)DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$id)->first();$this->audit($r,'update','task',$id,$item);return $this->ok($r,$item);}
    public function deleteTask(Request $r,string $id){$task=DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$id)->whereNull('deleted_at')->first();if(!$task)return $this->fail($r,'NOT_FOUND','task not found',404);DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$id)->update(['deleted_at'=>now(),'updated_at'=>now()]);$this->audit($r,'delete','task',$id,['deleted_at'=>now()->toIso8601String()]);return $this->ok($r,['deleted'=>true]);}
    public function submitReview(Request $r,string $id){$project=DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$id)->whereNull('deleted_at')->first();if(!$project)return $this->fail($r,'NOT_FOUND','project not found',404);$reviewers=DB::table('project_people')->where('tenant_id',$this->t($r))->where('project_id',$id)->where('project_role','reviewer')->pluck('user_id');$status=$reviewers->isEmpty()?'done':'review';DB::transaction(function()use($r,$id,$reviewers,$status){DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$id)->update(['status'=>$status,'updated_at'=>now()]);foreach($reviewers as $reviewer)DB::table('reviews')->updateOrInsert(['tenant_id'=>$this->t($r),'entity_type'=>'project','entity_id'=>$id,'reviewer_id'=>$reviewer],['id'=>(string)Str::uuid(),'status'=>'pending','updated_at'=>now(),'created_at'=>now()]);});$item=$this->project(DB::table('projects')->where('tenant_id',$this->t($r))->where('id',$id)->first());$this->audit($r,'submit_review','project',$id,['status'=>$status]);return $this->ok($r,$item);}
    public function checklist(Request $r,string $task){if(!DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$task)->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','task not found',404);return $this->ok($r,$this->rows(DB::table('checklist_items')->where('tenant_id',$this->t($r))->where('task_id',$task)->orderBy('item_order')));}
    public function addChecklist(Request $r,string $task){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400);if(!DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$task)->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','task not found',404);$d=$r->validate(['label'=>'required|string|max:255']);$id=(string)Str::uuid();$order=(int)(DB::table('checklist_items')->where('tenant_id',$this->t($r))->where('task_id',$task)->max('item_order')??-1)+1;DB::table('checklist_items')->insert(['id'=>$id,'tenant_id'=>$this->t($r),'task_id'=>$task,'label'=>trim($d['label']),'is_done'=>false,'item_order'=>$order,'created_at'=>now(),'updated_at'=>now()]);return $this->ok($r,(array)DB::table('checklist_items')->where('id',$id)->first(),201);}
    public function toggleChecklist(Request $r,string $task,string $id){$item=DB::table('checklist_items')->where('tenant_id',$this->t($r))->where('task_id',$task)->where('id',$id)->first();if(!$item)return $this->fail($r,'NOT_FOUND','checklist item not found',404);$d=$r->validate(['is_done'=>'required|boolean']);DB::table('checklist_items')->where('tenant_id',$this->t($r))->where('id',$id)->update(['is_done'=>$d['is_done'],'updated_at'=>now()]);return $this->ok($r,(array)DB::table('checklist_items')->where('id',$id)->first());}
    public function reviews(Request $r){$q=DB::table('reviews')->where('tenant_id',$this->t($r));if($r->filled('entity_type'))$q->where('entity_type',$r->query('entity_type'));if($r->filled('entity_id'))$q->where('entity_id',$r->query('entity_id'));return $this->ok($r,$this->rows($q->orderByDesc('updated_at')));}
    public function createReview(Request $r){if(!$r->header('Idempotency-Key'))return $this->fail($r,'VALIDATION_ERROR','Idempotency-Key is required',400);$d=$r->validate(['entity_type'=>'required|in:task,milestone,project','entity_id'=>'required|uuid','reviewer_id'=>'required|uuid','notes'=>'nullable|string|max:10000']);if(!DB::table('users')->where('tenant_id',$this->t($r))->where('id',$d['reviewer_id'])->exists())return $this->fail($r,'VALIDATION_ERROR','reviewer does not belong to this workspace',422);$id=(string)Str::uuid();DB::table('reviews')->insert(['id'=>$id,'tenant_id'=>$this->t($r),'entity_type'=>$d['entity_type'],'entity_id'=>$d['entity_id'],'reviewer_id'=>$d['reviewer_id'],'status'=>'pending','notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);return $this->ok($r,(array)DB::table('reviews')->where('id',$id)->first(),201);}
    public function updateReview(Request $r,string $id){$review=DB::table('reviews')->where('tenant_id',$this->t($r))->where('id',$id)->first();if(!$review)return $this->fail($r,'NOT_FOUND','review not found',404);$d=$r->validate(['status'=>'required|in:pending,approved,rejected,revision_requested','notes'=>'nullable|string|max:10000']);$d['updated_at']=now();DB::table('reviews')->where('tenant_id',$this->t($r))->where('id',$id)->update($d);return $this->ok($r,(array)DB::table('reviews')->where('id',$id)->first());}
    public function timeEntries(Request $r){$q=DB::table('time_entries')->where('tenant_id',$this->t($r));if($r->filled('task_id'))$q->where('task_id',$r->query('task_id'));return $this->ok($r,$this->rows($q->orderByDesc('started_at')));}
    public function startTime(Request $r){$d=$r->validate(['task_id'=>'required|uuid']);if(!DB::table('tasks')->where('tenant_id',$this->t($r))->where('id',$d['task_id'])->whereNull('deleted_at')->exists())return $this->fail($r,'NOT_FOUND','task not found',404);if(DB::table('time_entries')->where('tenant_id',$this->t($r))->where('user_id',$this->u($r)->id)->whereNull('ended_at')->exists())return $this->fail($r,'CONFLICT','an active timer already exists',409);$id=(string)Str::uuid();DB::table('time_entries')->insert(['id'=>$id,'tenant_id'=>$this->t($r),'task_id'=>$d['task_id'],'user_id'=>$this->u($r)->id,'started_at'=>now(),'auto_closed'=>false,'created_at'=>now(),'updated_at'=>now()]);return $this->ok($r,(array)DB::table('time_entries')->where('id',$id)->first(),201);}
    public function stopTime(Request $r){$entry=DB::table('time_entries')->where('tenant_id',$this->t($r))->where('user_id',$this->u($r)->id)->whereNull('ended_at')->orderByDesc('started_at')->first();if(!$entry)return $this->fail($r,'NOT_FOUND','active timer not found',404);$ended=now();$seconds=max(0,$ended->diffInSeconds($entry->started_at));DB::table('time_entries')->where('tenant_id',$this->t($r))->where('id',$entry->id)->update(['ended_at'=>$ended,'duration_seconds'=>$seconds,'updated_at'=>$ended]);return $this->ok($r,(array)DB::table('time_entries')->where('id',$entry->id)->first());}    public function productivity(Request $r){$tasks=DB::table('tasks')->where('tenant_id',$this->t($r))->whereNull('deleted_at');$total=(clone $tasks)->count();$done=(clone $tasks)->where('board_column','done')->count();$data=['totals'=>['tasks'=>$total,'completed'=>$done,'completion_rate'=>$total?round($done*100/$total,1):0],'teams'=>[]];if($r->query('format')==='pdf')return $this->ok($r,['download_url'=>'/api/v1/reports/productivity.pdf']);return $this->ok($r,$data);}
    public function productivityPdf(Request $r){$text="NPMS Productivity Report\nGenerated: ".now()->toIso8601String();return response($text,200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="productivity-report.pdf"']);}}
